package com.termux.app.workspace;

import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import com.termux.app.TermuxActivity;
import android.app.AlertDialog;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class ServerDiagnosticsTest {
    private ServerProfiles.Profile profile(){ServerProfiles.Profile p=new ServerProfiles.Profile();p.name="private-name";p.host="private.example";p.user="private-user";return p;}
    @Test public void safeTypedTelemetryNeverSerializesProfileOrExceptionPayload(){ServerProfiles.Profile p=profile();ServerDiagnostics.begin(p,ServerDiagnostics.Op.DIRECTORY).finish(25,3,512,new IOException("PRIVATE_TOKEN https://private/path"));String report=ServerDiagnostics.report(p);assertTrue(report.contains("DIRECTORY"));assertTrue(report.contains("OTHER_ERROR"));assertFalse(report.contains("PRIVATE_TOKEN"));assertFalse(report.contains(p.name));assertFalse(report.contains(p.host));assertFalse(report.contains(p.user));assertEquals(ServerDiagnostics.Op.RPC,ServerDiagnostics.operation("PRIVATE_SECRET_OP"));}
    @Test public void pausedIntervalAndInFlightEventsAreNotReconstructed(){ServerProfiles.Profile p=profile();ServerDiagnostics.Trace before=ServerDiagnostics.begin(p,ServerDiagnostics.Op.SEARCH);ServerDiagnostics.pause(p,true);String report=ServerDiagnostics.report(p);before.finish(5,0,1,null);assertEquals(report,ServerDiagnostics.report(p));ServerDiagnostics.Trace during=ServerDiagnostics.begin(p,ServerDiagnostics.Op.PROBE);ServerDiagnostics.pause(p,false);during.finish(1,0,1,null);assertTrue(ServerDiagnostics.snapshot(p).events.isEmpty());ServerDiagnostics.Trace after=ServerDiagnostics.begin(p,ServerDiagnostics.Op.PROPERTIES);after.finish(2,1,5,null);after.finish(2,1,5,null);assertEquals(1,ServerDiagnostics.snapshot(p).events.size());}
    @Test public void profilesAreIndependentAndOldPreferenceDefaultsOn()throws Exception{File file=new File(RuntimeEnvironment.application.getFilesDir(),"workspace-servers-v1.json");file.delete();try{ServerProfiles store=new ServerProfiles(RuntimeEnvironment.application);ServerProfiles.Profile one=profile(),two=profile();one.diagnosticsPaused=true;store.profiles.add(one);store.profiles.add(two);store.save();ServerProfiles reloaded=new ServerProfiles(RuntimeEnvironment.application);assertTrue(reloaded.profiles.get(0).diagnosticsPaused);assertFalse(reloaded.profiles.get(1).diagnosticsPaused);assertTrue(ServerDiagnostics.paused(reloaded.profiles.get(0)));assertFalse(ServerDiagnostics.paused(reloaded.profiles.get(1)));org.json.JSONObject old=two.json();old.remove("diagnosticsPaused");try(FileOutputStream out=new FileOutputStream(file)){out.write(new org.json.JSONObject().put("version",1).put("servers",new org.json.JSONArray().put(old)).toString().getBytes("UTF-8"));}assertFalse(new ServerProfiles(RuntimeEnvironment.application).profiles.get(0).diagnosticsPaused);}finally{file.delete();}}
    @Test public void queueTimingIsConsumedOnlyByFirstOperationAndClearedForNextJob()throws Exception{ServerWorkQueues queues=new ServerWorkQueues();ServerProfiles.Profile p=profile();try{queues.foreground.submit(()->{ServerDiagnostics.Trace one=ServerDiagnostics.begin(p,ServerDiagnostics.Op.METRICS),two=ServerDiagnostics.begin(p,ServerDiagnostics.Op.PROBE);assertTrue(one.waitMs>=0);assertEquals(-1,two.waitMs);one.finish(0,0,0,null);}).get(3,TimeUnit.SECONDS);}finally{queues.close();}assertEquals(-1,ServerDiagnostics.begin(p,ServerDiagnostics.Op.RPC).waitMs);}
    private View text(View root,String title){if(root instanceof TextView&&((TextView)root).getText().toString().equals(title))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View v=text(((ViewGroup)root).getChildAt(i),title);if(v!=null)return v;}return null;}
    @Test public void singlePauseButtonPersistsAndReopensAsResumeWithoutNetwork()throws Exception{TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(com.termux.R.style.Theme_Termux_Black);WorkspaceLanguage.select(a,"ru");File file=new File(a.getFilesDir(),"workspace-servers-v1.json");file.delete();ServerProfiles store=new ServerProfiles(a);ServerProfiles.Profile p=profile();store.profiles.add(p);store.save();AlertDialog dialog=ServerDiagnosticsUi.show(a,p,store);try{text(dialog.getWindow().getDecorView(),"Остановить журнал").performClick();assertTrue(p.diagnosticsPaused);assertNotNull(text(dialog.getWindow().getDecorView(),"Возобновить журнал"));assertTrue(new ServerProfiles(a).profiles.get(0).diagnosticsPaused);assertEquals(0,ServerDiagnostics.snapshot(p).events.size());}finally{dialog.dismiss();}dialog=ServerDiagnosticsUi.show(a,p,store);try{assertNotNull(text(dialog.getWindow().getDecorView(),"Возобновить журнал"));}finally{dialog.dismiss();file.delete();}}
    @Test public void saveFailureLeavesPauseChoiceAndCollectorUnchanged()throws Exception{TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(com.termux.R.style.Theme_Termux_Black);WorkspaceLanguage.select(a,"ru");ServerProfiles store=new ServerProfiles(a);store.writable=false;ServerProfiles.Profile p=profile();AlertDialog dialog=ServerDiagnosticsUi.show(a,p,store);try{text(dialog.getWindow().getDecorView(),"Остановить журнал").performClick();assertFalse(p.diagnosticsPaused);assertFalse(ServerDiagnostics.paused(p));assertNotNull(text(dialog.getWindow().getDecorView(),"Остановить журнал"));}finally{dialog.dismiss();}}
    @Test public void clipboardSizeIsBoundedAndExportStillHasFullText(){String report=new String(new char[200000]).replace('\0','x');String copied=DiagnosticsPanel.clipboardText(report);assertTrue(copied.length()<96000);assertTrue(copied.contains("save full report"));assertEquals(200000,report.length());}

    @Test public void ringIsBoundedAndVisibleSnapshotKeepsOnlyLastTwoHundred(){ServerProfiles.Profile p=profile();for(int i=0;i<35000;i++)ServerDiagnostics.begin(p,ServerDiagnostics.Op.METRICS).finish(10,1,1234,null);ServerDiagnostics.Snapshot data=ServerDiagnostics.snapshot(p);assertEquals(200,data.events.size());assertTrue(data.bytes<=ServerDiagnostics.LIMIT);assertTrue(data.dropped>0);assertTrue(ServerDiagnostics.report(p).length()<ServerDiagnostics.LIMIT+1200);}
}
